import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.CWWEQfK7.js";const p=JSON.parse('{"title":"User guide","description":"Follow a verified path from starting Ershu to reading the results of your first analysis.","frontmatter":{"page_id":"guide-index","description":"Follow a verified path from starting Ershu to reading the results of your first analysis."},"headers":[],"relativePath":"en/guide/index.md","filePath":"en/guide/index.md","lastUpdated":1786289447000}'),s={name:"en/guide/index.md"};function n(i,e,d,l,u,h){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="user-guide" tabindex="-1">User guide <a class="header-anchor" href="#user-guide" aria-label="Permalink to &quot;User guide&quot;">​</a></h1><p>These guides take you from an unconfigured Ershu environment to a project with a completed analysis. Each procedure explains what you should see before moving on.</p><h2 id="recommended-order" tabindex="-1">Recommended order <a class="header-anchor" href="#recommended-order" aria-label="Permalink to &quot;Recommended order&quot;">​</a></h2><ol><li><p><a href="./quick-start">Start Ershu and reach the sign-in page</a></p><p>Prepare the infrastructure, API, Worker, and frontend. When this is complete, the browser shows either the initial administrator setup page or the sign-in page.</p></li><li><p><a href="./create-first-project">Create your first project</a></p><p>Create the first administrator, configure model channels, and add a repository. When this is complete, the project overview shows the project and repository you created.</p></li><li><p><a href="./follow-a-run">Start and follow your first analysis</a></p><p>The first run must be a full-project run that includes every active repository. A successful run ends as <strong>Completed</strong> or <strong>Completed with warnings</strong>.</p></li><li><p><a href="./read-search-chat">Read documents, search the project, and ask questions</a></p><p>Follow citations from generated documents, search by keyword or meaning, and use project-scoped chat from the Docs page.</p></li></ol><h2 id="three-boundaries-to-know-first" tabindex="-1">Three boundaries to know first <a class="header-anchor" href="#three-boundaries-to-know-first" aria-label="Permalink to &quot;Three boundaries to know first&quot;">​</a></h2><ul><li>Public installation is not ready yet. The backend still obtains Core and the other components from private development sources, so <code>uv sync</code> cannot complete without access to those sources.</li><li>Creating a project does not start an analysis. You create the run separately from the project&#39;s Runs page.</li><li>The API only accepts and queues a run. If the Worker is not running, the run remains in the queue and produces no documents or indexes.</li></ul><p>If a step does not behave as described, start with the symptom table in <a href="./../development/troubleshooting">development troubleshooting</a>.</p>',7)])])}const m=t(s,[["render",n]]);export{p as __pageData,m as default};
